def casa2_espera_abertura():
    e = S.get("casa2")
    if not e or e.get("cena") != "abertura":
        return
    if time.time() - e["t0"] >= e["dur"]:
        e["cena"] = "lazaro"
        e["t_lazaro"] = time.time()
        e["chat"] = [("lazaro", CASA2_FALAS["lazaro"][1])]
        st.rerun(scope="app")


