def casa_repeticoes(pv):
    """Palavras e o lugar que o robô já está repetindo nesta conversa: vão para a lista do que evitar."""
    import re, collections
    falas = [t for r0, t in pv["msgs"] if r0 == "npc"]
    c = collections.Counter(w for t in falas for w in set(re.findall(r"[a-zà-ÿ]{4,}", t.lower())) if w not in CASA_PARADAS)
    rep_ = [w for w, n in c.most_common(8) if n >= 2]
    rot = next((x["rot"] for x in CASA_CENARIOS if x["k"] == pv.get("cen")), "")
    lugar = re.sub(r"^[^A-Za-zÀ-ÿ]+", "", rot).lower()
    return rep_, lugar


def casa_sem_beijo(txt, coracao=False):
    """Beijo só acontece quando o participante escolhe. O robô não se despede com beijo nem 'beija' em rubrica."""
    import re
    txt = re.sub(r"\*[^*]{1,80}\*", "", txt)   # rubricas tipo *te dá um beijo*
    txt = re.sub(r"\((?:[^()]{0,40}\b(?:beij|abraç|sorri|ri|pisca|olha)[^()]{0,40})\)", "", txt, flags=re.I)
    if not coracao:
        def _ab(m):
            ini = m.group(1)
            return ini + ("Um abraço" if (not ini.strip() or ini.strip()[-1:] in ".!?") else "um abraço")
        txt = re.sub(r"(^|[.!?,]\s*)(?:um |uns |mil |)beij(?:o|os|ão|inho|inhos)(?: no coração| pra você| procê| grande)?(?=\s*[,.!?…]|\s*$)", _ab, txt, flags=re.I)
        txt = re.sub(r"\b(te )beij(?:ar|o)\b", lambda m: m.group(1) + "dar um abraço", txt, flags=re.I)
    # o lugar já faz parte da paisagem: some com o 'aqui na rede', 'nessa bancada'...
    txt = re.sub(r"(?:,\s*)?\baqui (?:n[oa]s?|nessa|nesse|nesta|neste) (?:rede|bancada|cozinha|janela|piscina|cama|varanda|sala|jardim|borda|beira da piscina|quarto)(?: do jardim| da cozinha| da sala)?\b,?", "", txt, flags=re.I)
    txt = re.sub(r"\b(?:nessa|nesta) (?:rede|bancada|janela|cama|varanda)\b,?\s*", "", txt, flags=re.I)
    txt = re.sub(r"\s+([,.!?…])", r"\1", txt)
    txt = re.sub(r"(^|[.!?]\s+)([a-zà-ÿ])", lambda m: m.group(1) + m.group(2).upper(), txt)
    return re.sub(r"\s{2,}", " ", txt).strip()


def casa_sem_nome_repetido(e, pv, fala):
    """Gente não chama o outro pelo nome a cada frase: depois da primeira vez, o 'Caraca, Orlando,' vira só 'Caraca,'."""
    import re
    J = re.escape(e["jogador"])
    if not any(re.search(rf"\b{J}\b", t) for r0, t in pv["msgs"] if r0 == "npc"):
        return fala
    fala = re.sub(rf"^{J}\s*[,!.]\s*", "", fala)
    fala = re.sub(rf"\s*,\s*{J}\s*,", ",", fala)
    fala = re.sub(rf",\s*{J}\s*(?=[!?.…]|$)", "", fala)
    fala = re.sub(r"(^|[.!?]\s+)([a-zà-ÿ])", lambda m: m.group(1) + m.group(2).upper(), fala.strip())
    return fala


def casa_papo_responder(e, msg):
    pv = e["papo"]
    pid, tp = pv["pid"], pv["tipo"]
    p = e["parts"][pid]
    ultima = pv["n"] >= 2
    pv["msgs"].append(("user", msg))
    fala, nota, porque, emo = None, None, "", ""
    if ultima:   # a conversa termina sempre com a fala do participante real
        try:
            d = json.loads(groq_chat([{"role": "system", "content": casa_agente_base(e, pid) +
                f"Você puxou o assunto ({CASA_PAPO_TIPOS[tp][1]}): \"{pv['abertura']}\". A conversa inteira está abaixo. A última fala da pessoa encerra o papo.\n"
                "Dê uma NOTA de 0 a 10 para essa última fala, do jeito que você sentiu (escuta, empatia, interesse, humor, sinceridade) e diga em até 6 palavras por quê. "
                "Responda SOMENTE JSON: {\"nota\": 0, \"porque\": \"...\"}"},
                {"role": "user", "content": "\n".join(f"{'PESSOA' if r0 == 'user' else 'VOCÊ'}: {t0}" for r0, t0 in pv["msgs"])}], json_mode=True))
            nota = max(0, min(10, int(float(d.get("nota", 5)))))
            porque = str(d.get("porque", "")).strip()[:60]
        except Exception:
            nota = casa_papo_avaliar_off(msg, tp)
            porque = "me ouviu de verdade" if nota >= 7 else "foi educado" if nota >= 4 else "não prestou atenção"
        pv["notas"].append(nota)
        pv["porque"].append(porque)
        pv["n"] += 1
        pv["fim"] = True
        pv["fim_t"] = time.time()
        p["conversas"] = p.get("conversas", 0) + 1
        casa_mudar(e, pid, "eu", (nota - 5), (nota - 5)*.7)
        if nota >= 9:
            casa_conquistar(e, "papo_fogo")
        casa_cena_conversa(e, pid, msg, pv, titulo="")
        e["cena"]["quem"] = "eu"   # a última fala é sua: aparece na cena, sem voz
        return
    try:
        sistema = (casa_agente_base(e, pid) +
                   f"SEU OBJETIVO NESTA CONVERSA ({CASA_PAPO_TIPOS[tp][1]}): {CASA_AGENTE_OBJ[tp]}\n"
                   f"Você puxou o assunto assim: \"{pv['abertura']}\"\n"
                   + casa_regras_fala(e, pv) +
                   f"AGORA: {(CASA_AGENTE_ARCO_CONSELHO if tp == 'conselho' else CASA_AGENTE_ARCO)[min(pv['n'], 2)]} Responda diretamente ao que a pessoa acabou de dizer, curto (1 ou 2 frases), em português do Brasil. "
                   "Nada de política partidária, nada de ofensa.\n"
                   "PARA SER UMA CONVERSA INTELIGENTE: antes de falar, entenda o que a pessoa quis dizer de verdade (o sentimento por trás, não só as palavras). "
                   "Retome UMA ideia ou palavra exata que ela usou, mostre que isso mexeu com você e acrescente algo NOVO e concreto seu (um fato da sua vida, uma opinião com motivo, "
                   "uma lembrança, uma comparação inesperada). Tenha opinião própria e personalidade; não concorde com tudo. Se ela foi vaga, puxe um detalhe específico. "
                   "Se ela mudou de assunto, acompanhe com naturalidade e traga de volta com jeito. Nunca repita o que você já disse e nunca responda de forma genérica.\n"
                   "Depois dê uma NOTA de 0 a 10 para a última mensagem da pessoa, do jeito que você, com essa personalidade, sentiu: escuta, empatia, interesse, humor e sinceridade. "
                   "Resposta curta demais, fria, debochada, sem prestar atenção ou que manda fazer algo perigoso vale pouco; resposta que mostra que ouviu, se importou, "
                   "brincou junto ou foi sincera com carinho vale muito. Em lorota, entrar na brincadeira ou duvidar com bom humor são bons; numa polêmica, discordar com respeito também é bom.\n"
                   "EMOÇÃO da sua fala (para o tom de voz): alegre, empolgado, triste, bravo, calmo, ironico ou neutro.\n"
                   "Responda SOMENTE JSON: {\"pensamento\": \"em 1 frase: o que a pessoa quis dizer e como você se sente com isso\", \"fala\": \"...\", \"nota\": 0, "
                   "\"porque\": \"até 6 palavras, ex.: me ouviu de verdade\", \"emocao\": \"neutro\"}")
        msgs = [{"role": "system", "content": sistema}]
        for r0, t0 in pv["msgs"]:
            msgs.append({"role": "user" if r0 == "user" else "assistant", "content": t0 if r0 == "user" else json.dumps({"fala": t0}, ensure_ascii=False)})
        d = json.loads(groq_chat(msgs, json_mode=True))
        fala = str(d.get("fala", "")).strip()[:420]
        nota = max(0, min(10, int(float(d.get("nota", 5)))))
        porque = str(d.get("porque", "")).strip()[:60]
        emo = str(d.get("emocao", "")).strip().lower()
    except Exception:
        fala = None
    if nota is None:
        nota = casa_papo_avaliar_off(msg, tp)
    if not fala:
        o = "a" if p["sexo"] == "F" else "o"
        bom = ["Nossa... obrigad{o} por me ouvir assim. Faz tempo que ninguém presta atenção em mim desse jeito.", "Gostei de você ter falado isso. Sério, me fez bem.",
               "Hahaha, você é demais! Tô adorando esse papo.", "É exatamente isso que eu precisava ouvir. E você, como tá aqui dentro?"]
        meio = ["Hum... faz sentido. Nunca tinha pensado por esse lado.", "Pode ser... vou pensar nisso.", "Entendi. Cada um vê de um jeito, né?"]
        ruim = ["Ah... tá. Achei que você ia se importar um pouco mais.", "Nossa, você nem prestou atenção no que eu falei, né?", "Esquece, deixa pra lá."]
        fala = random.choice(bom if nota >= 7 else meio if nota >= 4 else ruim).replace("{o}", o)
        if ultima:
            fala += " " + (random.choice(["Adorei conversar com você.", "Vou lembrar dessa conversa."]) if nota >= 6 else random.choice(["Bom, vou lá pra dentro.", "Depois a gente se fala."]))
        porque = "me ouviu de verdade" if nota >= 7 else "foi educado" if nota >= 4 else "não prestou atenção"
    if tp == "historia" and not ultima and nota >= 7:   # quem se sente ouvido abre mais um capítulo da vida
        k = p.get("cap_rev", 0)
        if casa_lenda(p) and k in (1, 2) and (k == 1 or (nota >= 8 and sum(pv["notas"] + [nota])/(len(pv["notas"]) + 1) >= 7.5)):
            fala = fala.split(".")[0].strip() + ". " + ("Vou te contar uma coisa que eu nunca contei pra ninguém aqui dentro... " if k == 2 else "Sabe... tem mais. ") + casa_lenda_revelar(e, pid, k)
    fala = casa_sem_beijo(fala, tp == "coracao") or "Gostei de conversar com você."
    if emo not in ("alegre", "empolgado", "triste", "bravo", "calmo", "ironico", "neutro"):
        emo = ""   # sem emoção da IA: a voz lê a emoção no próprio texto
    fala = casa_sem_nome_repetido(e, pv, fala)
    fala = casa_variar(e, casa_gen(e, fala, pid), pid)
    e["_sem_variar"] = True
    pv["notas"].append(nota)
    pv["porque"].append(porque)
    pv["msgs"].append(("npc", fala))
    pv["n"] += 1
    p["conversas"] = p.get("conversas", 0) + 1
    p["revelado"] = True
    casa_mudar(e, pid, "eu", (nota - 5), (nota - 5)*.7)
    if nota >= 9:
        casa_conquistar(e, "papo_fogo")
    if pv["n"] >= 3:
        pv["fim"] = True
    casa_cena_conversa(e, pid, fala, pv, titulo="")
    e["cena"].setdefault("extra", {})["emo"] = emo


def casa_papo_media(pv):
    return round(sum(pv["notas"])/len(pv["notas"]), 1) if pv["notas"] else 2.0


def casa_bastidor(e):
    """Enquanto você conversa, os robôs também conversam entre si. Uma cena curta aparece."""
    r = e["rodada"]
    robos = [x for x in casa_vivos(e, False)]
    if len(robos) < 2:
        return
    cont = {x: sum(1 for b in r["bast"] if b["a"] == x) for x in robos}
    a = min(robos, key=lambda x: (cont[x], random.random()))
    b = random.choice([x for x in robos if x != a])
    q = r["qual"][a]
    pa, pb = e["parts"][a], e["parts"][b]
    dele = "dela" if pa["sexo"] == "F" else "dele"
    ob = "a" if pb["sexo"] == "F" else "o"
    ass = CASA_PAPO_TIPOS[r["tipos"][a]][3].replace("{dele}", dele)
    cen = random.choice([c for c in CASA_CENARIOS if c["k"] not in ("cama",)])
    if q >= 7:
        reac, fala = f"{pb['nome']} ficou emocionad{ob} e não parou de comentar", random.choice(["Gente, que história! Arrepiei aqui.", "Nossa, você me ganhou com essa conversa.", "Eu precisava ouvir isso hoje, obrigad" + ob + "."])
    elif q >= 4.5:
        reac, fala = f"{pb['nome']} ouviu com educação", random.choice(["Hum, interessante... sério?", "Entendi. É, cada um com a sua vida.", "Legal... e aí?"])
    else:
        reac, fala = f"{pb['nome']} bocejou e mudou de assunto", random.choice(["Tá, tá... vou pegar uma água.", "Hum. Você já me contou isso, né?", "Nossa, que papo... depois a gente conversa."])
    txt = f"{cen['rot']}: **{pa['nome']}** contou para **{pb['nome']}** {ass}. {reac}."
    e["parts"][b]["memoria"].append(f"Semana {e['semana']}: ouviu {pa['nome']} falar de {ass} e achou {'ótimo' if q >= 7 else 'ok' if q >= 4.5 else 'chato'}")
    casa_mudar(e, b, a, round((q - 5)*1.5), round(q - 5))
    r["bast"].append(dict(a=a, b=b, texto=txt, fala=fala, cen=cen["k"], q=q))


def casa_papo_fechar(e):
    pv, r = e["papo"], e["rodada"]
    pid = pv["pid"]
    media = casa_papo_media(pv)
    r["notas"][pid] = media

    nm = casa_nome(e, pid)
    ic, nmt, _, _ = CASA_PAPO_TIPOS[pv["tipo"]]
    casa_lembrar(e, pid, f"teve uma conversa {'linda' if media >= 7.5 else 'boa' if media >= 5.5 else 'fraca' if media >= 3.5 else 'péssima'} com você ({nmt.lower()})")
    casa_reg(e, f"{ic} Você conversou com {nm} ({nmt.lower()}). Emocionômetro: {media}/10.")
    if pv["tipo"] == "conselho" and media >= 8:
        casa_conquistar(e, "conselheiro")
    e.setdefault("papos", {})[pid] = dict(tipo=pv["tipo"], tema=pv["tema"], nota=media, msgs=pv["msgs"], porque=pv["porque"])
    if pv["tipo"] == "coracao" and e["parts"][pid]["sexo"] != e["sexo"] and media >= 7.5:
        r["beijo"] = pid   # o clima esquentou: a pessoa pergunta se pode te beijar, e quem decide é você
    e["papo"] = None
    casa_bastidor(e)
    r["i"] += 1


def casa_papo_seguir(e):
    r = e["rodada"]
    if r["i"] >= len(r["ordem"]):
        casa_confess_preparar(e)
    else:
        casa_papo_abrir(e)


def casa_emocionometro_html(de, para, rotulo="", sub="", som=True, altura=62):
    """Emocionômetro em barra: o marcador corre da vaia aos aplausos, com som de plateia conforme a nota."""
    return f"""<!doctype html><html><head><meta charset='utf-8'><style>
body{{margin:0;background:transparent;font-family:system-ui;color:#fff}}
#c{{background:#120c2c;border:1px solid #7c4dff;border-radius:12px;padding:5px 10px;display:flex;align-items:center;gap:10px}}
#t{{font-weight:900;font-size:.72rem;letter-spacing:1px;color:#ffd600;white-space:nowrap}}
#w{{flex:1;position:relative;height:14px;border-radius:8px;background:linear-gradient(90deg,#ff1744,#ff9100 35%,#ffea00 60%,#00e676 82%,#ff3d00)}}
#m{{position:absolute;top:-5px;width:6px;height:24px;margin-left:-3px;background:#fff;border-radius:3px;box-shadow:0 0 8px #fff}}
#n{{font-weight:900;font-size:1.05rem;min-width:34px;text-align:right}}
#r{{font-size:.78rem;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:42%}}
#e{{display:flex;justify-content:space-between;font-size:.7rem;margin-top:1px;padding:0 4px}}
@media (max-width:520px){{#t{{display:none}} #r{{max-width:34%;font-size:.7rem}}}}
</style></head><body><div id='c'><span id='t'>🎚️ EMOCIONÔMETRO</span><div style='flex:1'><div id='w'><div id='m'></div></div><div id='e'><span>😴</span><span>😐</span><span>🙂</span><span>😍</span><span>🔥</span></div></div>
<span id='n'></span><span id='r' title='{_html.escape(sub)}'>{_html.escape(rotulo)}</span></div>
<script>
const de = {de}, para = {para}, m = document.getElementById('m'), n = document.getElementById('n'); let t0 = null;
function f(ts){{ if (!t0) t0 = ts; const k = Math.min(1, (ts - t0)/1500), e2 = 1 - Math.pow(1 - k, 3);
  const bal = k < 1 ? Math.sin(k*18)*(1 - k)*4 : 0, v = de + (para - de)*e2;
  m.style.left = Math.max(0, Math.min(100, v*10 + bal)) + '%'; n.textContent = v.toFixed(1); if (k < 1) requestAnimationFrame(f); }}
requestAnimationFrame(f);
if ({'true' if som else 'false'} && de !== para) try {{
  const A = new (window.AudioContext || window.webkitAudioContext)(), T = A.currentTime;
  const ruido = (dur, vol, freq, q) => {{ const b = A.createBuffer(1, A.sampleRate*dur, A.sampleRate), d = b.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = (Math.random()*2 - 1)*(para >= 7 ? (Math.random() < .3 ? 1 : .3) : 1);
    const s = A.createBufferSource(), fl = A.createBiquadFilter(), g = A.createGain(); s.buffer = b; fl.type = 'bandpass'; fl.frequency.value = freq; fl.Q.value = q;
    g.gain.setValueAtTime(0, T); g.gain.linearRampToValueAtTime(vol, T + .25); g.gain.linearRampToValueAtTime(0, T + dur); s.connect(fl).connect(g).connect(A.destination); s.start(T); }};
  if (para >= 7) {{ ruido(2.6, .5, 2200, .6); ruido(2.6, .3, 900, .8); }}
  else if (para >= 4) ruido(1.8, .22, 500, 1.2);
  else {{ const o = A.createOscillator(), g = A.createGain(), l = A.createOscillator(), lg = A.createGain(); o.type = 'sawtooth'; o.frequency.value = 140;
    l.frequency.value = 5; lg.gain.value = 18; l.connect(lg).connect(o.frequency); g.gain.setValueAtTime(0, T); g.gain.linearRampToValueAtTime(.18, T + .3); g.gain.linearRampToValueAtTime(0, T + 1.8);
    o.connect(g).connect(A.destination); o.start(T); l.start(T); o.stop(T + 1.9); l.stop(T + 1.9); ruido(1.8, .15, 400, 1); }}
}} catch (err) {{}}
</script></body></html>"""


def casa_emo_rotulo(v):
    return ("😴 Que papo chato..." if v < 2.5 else "😐 A plateia bocejou" if v < 4 else "🙂 Papo morno" if v < 5.5 else "😊 A plateia gostou" if v < 7
            else "😍 A casa se emocionou!" if v < 8.5 else "🔥 A CASA PAROU!")


def casa_emo_barra(pv):
    media = casa_papo_media(pv) if pv["notas"] else 5.0
    ant = (sum(pv["notas"][:-1])/len(pv["notas"][:-1])) if len(pv["notas"]) > 1 else 5.0
    rot = (casa_emo_rotulo(media) + (f" · “{pv['porque'][-1]}”" if pv["porque"] and pv["porque"][-1] else "")) if pv["notas"] else "🎙️ A plateia espera a sua resposta"
    jogo_html(casa_emocionometro_html(round(ant, 1), round(media, 1), rot, "", som=bool(pv["notas"])), 62)


def casa_popup(titulo):
    """Pop-up que só fecha com a escolha feita (em versões antigas do Streamlit, um pop-up comum)."""
    try:
        return st.dialog(titulo, dismissible=False)
    except TypeError:
        return st.dialog(titulo)


def casa_contagem(e, ate, texto, acao):
    """Mostra 'em N s...' e, quando o tempo acaba, executa a ação e recarrega a tela, sem botão."""
    if time.time() >= ate:
        acao()
        st.rerun()

    @st.fragment(run_every=1)
    def _cont():
        resta = ate - time.time()
        if resta <= 0:
            st.rerun(scope="app")
        st.info(texto.replace("{s}", str(int(resta) + 1)))
    _cont()


@casa_popup("💘 O clima esquentou")
def casa_dlg_beijo(e):
    r = e["rodada"]
    pid = r["beijo"]
    nm = casa_nome(e, pid)
    st.markdown(f"**{nm}** chega bem pertinho e pergunta baixinho: *“Posso te dar um beijo?”*  \nQuem decide é você.")
    c1, c2, c3 = st.columns(3)
    esc = "beijo" if c1.button("💋 Beijar", type="primary", use_container_width=True) else "abraco" if c2.button("🤗 Só um abraço", use_container_width=True) \
        else "nao" if c3.button("🙅 Não quero", use_container_width=True) else None
    if not esc:
        return
    r["beijo"] = None
    r["prox_t"] = time.time() + 7
    if esc == "beijo":
        casa_mudar(e, pid, "eu", 8, 6)
        r["notas"][pid] = min(10, r["notas"][pid] + .5)
        e.setdefault("beijos", []).append(dict(pid=pid, sem=e["semana"], lugar="no quarto"))
        casa_lembrar(e, pid, "te beijou e não para de pensar em você")
        casa_reg(e, f"💋 {e['jogador']} e {nm} se beijaram no quarto!")
        casa_conquistar(e, "beijo")
        for x in casa_vivos(e, False):
            if x != pid:
                casa_mudar(e, x, pid, -6, -4)   # a casa inteira viu
        casa_cena(e, "reality_quarto", [pid], random.choice(["Meu coração tá disparado...", "Eu sabia que não era só eu sentindo isso.", "Promete que não foi por causa do jogo?"]),
                  quem=pid, enc="beijo", eu=True, titulo="", extra=dict(noite=True))
    elif esc == "abraco":
        casa_mudar(e, pid, "eu", 3, 4)
        casa_cena(e, "reality_quarto", [pid], "Tudo bem... um abraço seu já vale muito.", quem=pid, enc="abraco", eu=True, titulo="", extra=dict(noite=True))
    else:
        casa_mudar(e, pid, "eu", -1, 2)
        casa_cena(e, "reality_quarto", [pid], "Tudo bem, eu respeito. Obrigad" + ("a" if e["parts"][pid]["sexo"] == "F" else "o") + " por ser sincer"
                  + ("a" if e["sexo"] == "F" else "o") + ".", quem=pid, enc="conversa", eu=True, titulo="", extra=dict(noite=True))
    st.rerun()


@casa_popup("🗳️ Seu voto: quem deve sair?")
def casa_dlg_confess(e):
    nm = lambda x: casa_nome(e, x)
    r = e["rodada"]
    st.caption("Escolha e diga o motivo bem rápido. Depois todos votam no confessionário, um por um, e os 3 mais votados saem.")
    alvo = st.radio("Em quem você vota?", casa_vivos(e, False), format_func=lambda x: f"{nm(x)} · {CASA_PAPO_TIPOS[r['tipos'][x]][1]}", key="cs_cfal")
    mot = st.text_input("Por quê?", key="cs_cfmt", max_chars=160, placeholder="Porque a nossa conversa não rendeu...")
    if st.button("✅ Votar", type="primary", key="cs_cfgo", use_container_width=True):
        if len((mot or "").strip()) < 4:
            st.error("Diga o motivo do seu voto.")
            return
        with st.spinner("A casa está entrando no confessionário..."):
            casa_confess_votar(e, alvo, mot.strip())
        st.rerun()


@casa_popup("🎤 Por que você merece vencer?")
def casa_dlg_discurso(e):
    fin = casa_vivos(e)
    st.markdown("**Você está na final!** Em **2 linhas**, diga ao Brasil por que você merece o prêmio. Depois os finalistas discursam na frente da casa e o público vota.")
    txt = st.text_area("Seu discurso", key="cs_fin_t", max_chars=170, height=90, placeholder="Eu mereço ganhar porque joguei com o coração do começo ao fim...")
    if st.button("✅ OK", type="primary", key="cs_fin_b", use_container_width=True):
        if len(txt.strip()) < 15:
            st.error("Escreva pelo menos uma frase.")
            return
        with st.spinner("O Brasil está ouvindo..."):
            nota, reac = casa_aval_defesa(e, txt.strip())
            e["defesa"]["eu"] = dict(txt=txt.strip(), nota=nota, reac=reac)
            casa_pop(e, "eu", round((nota - 5)*1.2))
            casa_reg(e, f"🎤 Discurso da final: nota {nota}/10. {reac}")
            casa_final_iniciar(e, fin)
        st.rerun()


def casa_papo_barra(e):
    """Acima da cena: o Emocionômetro e o campo para responder. Fim de conversa, próxima pessoa e confessionário seguem sozinhos."""
    r = e.get("rodada")
    if not r:
        return
    nm = lambda x: casa_nome(e, x)
    k = f"cs_rd{r['i']}"
    tot = len(r["ordem"])
    if r.get("beijo"):
        casa_dlg_beijo(e)
        return
    pv = e.get("papo")
    if not pv:   # entre uma conversa e outra (depois do beijo, por exemplo): segue sozinho
        prox = r["ordem"][r["i"]] if r["i"] < tot else None
        casa_contagem(e, r.setdefault("prox_t", time.time() + 6),
                      f"Em {{s}} s você vai conversar com **{nm(prox)}**" if prox else "Em {s} s: todos para o confessionário 🎥",
                      lambda: (r.pop("prox_t", None), casa_papo_seguir(e)))
        return
    pid = pv["pid"]
    casa_emo_barra(pv)
    if pv["fim"]:   # a conversa terminou com a sua fala: 5 segundos e já vem a próxima pessoa
        prox = r["ordem"][r["i"] + 1] if r["i"] + 1 < tot else None
        def seguir():
            casa_papo_fechar(e)
            if not r.get("beijo"):
                casa_papo_seguir(e)
        casa_contagem(e, pv.get("fim_t", time.time()) + 5,
                      (f"✅ Conversa com {nm(pid)} encerrada · {casa_papo_media(pv)}/10. " +
                       (f"Em {{s}} s você vai falar com **{nm(prox)}**" if prox else "Em {s} s: fim das conversas, hora de votar 🗳️")), seguir)
        return
    with st.form(k + f"f{pv['n']}", clear_on_submit=True, border=False):
        c1, c2 = st.columns([5, 1], vertical_alignment="bottom")
        msg = c1.text_input("Sua resposta", max_chars=500, placeholder=f"Responda {nm(pid)}... ({pv['n'] + 1} de 3)", label_visibility="collapsed")
        if c2.form_submit_button("💬 Falar", type="primary", use_container_width=True) and msg.strip():
            with st.spinner(f"{nm(pid)} está ouvindo..."):
                casa_papo_responder(e, msg.strip())
            st.rerun()


def casa_rodada_ui(e):
    """Embaixo da cena: só o andamento; a conversa já aparece na própria cena."""
    r = e["rodada"]
    nm = lambda x: casa_nome(e, x)
    pv = e.get("papo")
    st.markdown("**Conversas:** " + " ".join(("✅" if x in r["notas"] else "💬" if pv and pv["pid"] == x else "⚪") + f" {nm(x)}" for x in r["ordem"]))
    if pv and len(pv["msgs"]) > 1:
        with st.expander("📜 Rever a conversa"):
            for r0, t0 in pv["msgs"]:
                st.markdown(f"**{e['jogador'] if r0 == 'user' else nm(pv['pid'])}:** {t0}")


# ---------- 🎥 Confessionário: todos votam e explicam; os 3 mais votados saem
def casa_favorito(e):
    """Se alguém ficou bem acima dos outros no Emocionômetro com você, a casa percebe e fica com ciúme."""
    n = {x: v for x, v in e["rodada"]["notas"].items() if e["parts"][x]["vivo"]}
    if len(n) < 2:
        return None
    o = sorted(n, key=lambda x: -n[x])
    if n[o[0]] >= 7 and n[o[0]] - n[o[1]] >= 1.5:
        return o[0]
    return None


def casa_confess_voto(e, v, fav):
    """Voto de um robô e o motivo, pesando a conversa com você, o assunto de cada um e o ciúme."""
    r = e["rodada"]
    notas = r["notas"]
    media_eu = sum(notas.values())/len(notas) if notas else 5
    cands = [x for x in casa_vivos(e) if x != v]
    best, bs, bmot = None, -99, ""
    for t in cands:
        if t == "eu":
            if v == fav:
                continue
            nv = notas.get(v, 3)
            comp = {"conversa": (5.2 - nv)*1.3, "geral": (5.2 - media_eu)*.5}
        else:
            comp = {"assunto": (6 - r["qual"][t])*1.25, "afinidade": (50 - casa_op(e, v, t))/12}
            if t == fav and v != fav:
                comp["ciume"] = 2.8
        s = sum(comp.values()) + random.gauss(0, 1)
        if s > bs:
            best, bs, bmot = t, s, max(comp, key=comp.get)
    return best, casa_confess_motivo(e, v, best, bmot)


def casa_confess_motivo(e, v, t, mot):
    r = e["rodada"]
    J = e["jogador"]
    sxt = e["sexo"] if t == "eu" else e["parts"][t]["sexo"]
    ela, a = ("ela", "a") if sxt == "F" else ("ele", "o")
    if mot == "ciume":
        return random.choice([f"Passou a semana inteira grudad{a} n{'a' if e['sexo'] == 'F' else 'o'} {J}. Isso é jogo combinado.",
                              f"Todo mundo viu: {ela} e {J} viraram unha e carne. Lá fora {ela} protege {J}, e aqui eu protejo o meu jogo.",
                              f"Eu vi como {ela} olha pr{'a' if e['sexo'] == 'F' else 'o'} {J}. Dupla assim chega na final junta, e eu não vou deixar."])
    if mot in ("conversa", "geral"):
        nv = r["notas"].get(v, 3)
        rot = next((c["rot"] for c in CASA_CENARIOS if c["k"] == CASA_PAPO_TIPOS[r["tipos"][v]][2]), "na casa")
        if nv < 4:
            return random.choice([f"Eu abri o meu coração {rot[2:].strip().lower()} e {ela} nem prestou atenção.", "A nossa conversa não rendeu nada. Senti que não me ouviu.",
                                  f"Eu precisava de alguém pra me ouvir e {ela} me tratou com frieza."])
        return random.choice(["A nossa conversa foi ok, mas eu senti que faltou verdade.", "Gostei do papo, mas eu acho que tem gente que se entregou mais aqui dentro.",
                              f"Nada contra, mas {ela} conversou melhor com os outros do que comigo."])
    if mot == "assunto":
        tp = CASA_PAPO_TIPOS[r["tipos"][t]][1].lower()
        return random.choice([f"O assunto que {ela} trouxe não convenceu ninguém.", f"Ouvi {ela} falar de {tp} e, sinceramente, não me tocou.",
                              f"Pra mim foi o papo mais fraco da casa.", f"{ela.capitalize()} falou, falou e não disse nada."])
    return random.choice(["É com quem eu tenho menos afinidade.", "A gente não se bica desde o começo.", "Não confio. Simples assim.", "É quem menos se conectou comigo."])


def casa_confess_motivos_ia(e, votos, mots):
    """Cada agente explica o voto com as próprias palavras, lembrando do que viveu na casa (um pedido só para todos)."""
    if not S.get("groq_key") or not votos:
        return
    J = e["jogador"]
    nm = lambda x: J if x == "eu" else casa_nome(e, x)
    r = e["rodada"]
    try:
        info = []
        for v, t in votos:
            p = e["parts"][v]
            d = (e.get("papos") or {}).get(v) or {}
            info.append(dict(quem=p["nome"], jeito=CASA_ESTILO[p["perso"]][:120], vota_em=nm(t), motivo_base=mots[v],
                             conversa_com_jogador=dict(assunto=CASA_PAPO_TIPOS[r["tipos"][v]][1], ficou=("ótima" if d.get("nota", 0) >= 7.5 else "boa" if d.get("nota", 0) >= 5.5 else "fraca"),
                                                       jogador_disse=[t0[:100] for r0, t0 in d.get("msgs", []) if r0 == "user"][:2]),
                             bastidores=[b["texto"].replace("**", "") for b in r["bast"] if v in (b["a"], b["b"])][-2:]))
        d = json.loads(groq_chat([{"role": "system", "content":
            f"Reality show brasileiro, confessionário. O participante humano se chama {J}. Para cada participante abaixo, escreva o motivo do voto em 1 ou 2 frases, "
            "em português do Brasil, no jeito de falar dele, citando algo concreto que ele viveu (a conversa, o que ouviu nos bastidores, o ciúme). "
            "Mantenha o sentido do motivo_base. Sem ofensas pesadas. Não comece com 'Eu sou' nem repita o nome de quem recebe o voto no começo. "
            "Responda SOMENTE JSON: {\"motivos\": [\"...\", ...]} na mesma ordem."},
            {"role": "user", "content": json.dumps(info, ensure_ascii=False)}], json_mode=True))
        ms = d.get("motivos") or []
        for (v, t), m in zip(votos, ms):
            m = str(m).strip()[:240]
            if len(m) > 12:
                mots[v] = m
    except Exception:
        pass


def casa_confess_preparar(e):
    e["fase"] = "confess"
    e["papo"] = None
    vivos = casa_vivos(e, False)
    casa_cena(e, "confessionario", [vivos[0]] if vivos else [], "Chegou a hora. Cada um vai entrar no confessionário, dizer quem deve sair e por quê. Os três mais votados deixam a casa hoje.",
              quem="Apresentador", titulo="🎥 O Confessionário", enc="confessionario", eu=False)


def casa_confess_ui(e):
    """Acabaram as conversas: o pop-up do seu voto abre sozinho."""
    st.markdown("### 🎥 Confessionário")
    st.caption("Vote em quem deve sair. Depois todos votam, um por um, e os **3 mais votados saem** de uma vez.")
    casa_dlg_confess(e)


def casa_confess_votar(e, meu, motivo):
    fav = casa_favorito(e)
    robos = casa_vivos(e, False)
    votos, mots = [], {}
    for v in robos:
        t, m = casa_confess_voto(e, v, fav)
        votos.append((v, t))
        mots[v] = m
    casa_confess_motivos_ia(e, votos, mots)
    if e["vivo"]:
        votos.insert(random.randint(0, len(votos)), ("eu", meu))
        mots["eu"] = motivo
        e["motivo_eu"] = motivo
    cands = casa_vivos(e)
    cont = {x: 0 for x in cands}
    for v, t in votos:
        cont[t] += 1
        if t != "eu" and v != "eu":
            casa_lembrar(e, t, f"{casa_nome(e, v)} votou em mim no confessionário")
    ordem = sorted(cands, key=lambda x: -cont[x])
    nsai = min(3, max(0, len(cands) - 3))
    corte = cont[ordem[nsai - 1]] if nsai else 0
    certos = [x for x in cands if cont[x] > corte]
    emp = [x for x in cands if cont[x] == corte]
    random.shuffle(emp)
    sorteio = len(certos) + len(emp) > nsai and nsai > 0
    sai = (certos + emp)[:nsai]
    sai.sort(key=lambda x: -cont[x])
    nm = lambda x: casa_nome(e, x)
    fin = [x for x in cands if x not in sai]
    poema = casa_poema_eliminacao(e, sai, fin)
    frase = (poema + f" O confessionário falou. Deixam a casa hoje: {', '.join(nm(x) for x in sai[:-1])} e {nm(sai[-1])}."
             + f" {', '.join(nm(x) for x in fin[:-1])} e {nm(fin[-1])}: vocês são os finalistas!")
    e["resultado"] = dict(sai=sai, fin=fin, cont=cont, votos=votos, mots=mots, sorteio=sorteio, sorteados=[x for x in emp if x in sai] if sorteio else [], frase=frase,
                          revelado=False, fav=fav)
    e["fase"] = "confess_res"
    if "eu" in cands and cont["eu"] == 0 and "eu" not in sai:
        casa_conquistar(e, "intocavel")
    itens = [casa_item_voto(e, v, t, acao="sair", mot=mots[v]) for v, t in votos]
    casa_playlist_cena(e, itens, "🎥 Confessionário: quem deve sair?")
    e["cena"]["extra"]["fimTexto"] = "Votos dados. Todos para a sala!"
    npar = [x for x in sai if x != "eu"]
    resto = [x for x in casa_vivos(e, False) if x not in npar]
    e["cena"]["prox"] = casa_cena_dict(e, "reality_sala", npar + resto[:6 - len(npar)], frase, quem="Apresentador", titulo="🎥 RESULTADO DO CONFESSIONÁRIO",
                                       capitulo="A grande noite", enc="eliminacao", eu=True, maxn=6,
                                       extra=dict(npar=len(npar), parEu="eu" in sai, sai=-1, telao="host"))
    e["play_ate"] = e.get("play_ate", time.time()) + 4 + len(frase)*.075   # o apresentador termina a poesia e os nomes antes da despedida
    casa_reg(e, "🎥 Confessionário: " + "; ".join(f"{e['jogador'] if v == 'eu' else nm(v)} votou em {e['jogador'] if t == 'eu' else nm(t)}" for v, t in votos) + ".")


CASA_POEMAS = [
    "Boa noite, Brasil! Cinco conversas, cinco corações abertos. Teve riso, teve lágrima, teve segredo contado baixinho. Mas a casa é como a vida: nem todo mundo cabe na mesma foto.",
    "Boa noite! Hoje eu não trago notícia, eu trago espelho. Quem falou com o coração foi ouvido. Quem falou só com a boca, a casa percebeu. E o confessionário não esquece.",
    "Boa noite, casa! Vocês aprenderam que conversa boa não é a que fala mais, é a que escuta melhor. Alguns aqui escutaram o mundo. Outros só escutaram a si mesmos.",
    "Boa noite! Uma casa é feita de paredes, mas um jogo é feito de pontes. Hoje três pontes caem. Não por falta de coragem, mas porque o outro lado decidiu não atravessar.",
    "Boa noite, Brasil! Teve quem contou a própria história, teve quem inventou uma, teve quem pediu ajuda e teve quem ajudou. Hoje, a casa escolheu quem segue com ela.",
]


def casa_poema_eliminacao(e, sai, fin):
    """Como o Bial: uma poesia curtinha antes de dizer quem sai (sem entregar os nomes)."""
    if S.get("groq_key"):
        try:
            nm = lambda x: e["jogador"] if x == "eu" else casa_nome(e, x)
            r = e.get("rodada") or {}
            pistas = "; ".join(f"{nm(x)}: {CASA_PAPO_TIPOS[r['tipos'][x]][1].lower() if x in r.get('tipos', {}) else 'o participante de fora'}" for x in sai + fin)
            d = json.loads(groq_chat([{"role": "system", "content":
                "Você é o apresentador de um reality show brasileiro, no estilo dos discursos poéticos de eliminação. Escreva uma poesia em prosa, curta (3 ou 4 frases, até 60 palavras), "
                "começando com 'Boa noite', emocionante, com imagens simples sobre conversa, escuta, coragem e convivência. NÃO diga nomes, NÃO diga quem sai, NÃO fale de votos, sorteio ou empate. "
                "Responda SOMENTE JSON: {\"poema\": \"...\"}"},
                {"role": "user", "content": f"Os assuntos que cada um trouxe para a casa: {pistas}"}], json_mode=True))
            p = str(d.get("poema", "")).strip()
            if 40 < len(p) < 500 and not any(nm(x).lower() in p.lower() for x in sai + fin):
                return p
        except Exception:
            pass
    return random.choice(CASA_POEMAS)


def casa_confess_res_ui(e):
    """Votos, resultado, saída e o caminho até a final: tudo segue sozinho, no tempo da cena."""
    r = e["resultado"]
    nm = lambda x: casa_nome(e, x)
    if not r.get("revelado"):
        st.markdown("### 🎥 A casa está votando")
        st.caption("Um por um, cada participante entra no confessionário, diz o nome, em quem vota e por quê. Depois o apresentador anuncia quem sai.")

        def revelar():
            r["revelado"] = True
            sai = r["sai"]
            casa_saida(e, sai)
            fav = r.get("fav")
            if fav in sai and "eu" not in sai:   # o seu favorito sai: despedida emocionada
                e["cena"]["texto"] = casa_gen(e, f"{e['jogador']}, cuida de você aí dentro, tá? Você foi a melhor conversa que eu tive nessa casa. Lá fora a gente se encontra.", fav)
                e["cena"]["quem"] = fav
                e["cena"]["npcs"] = [fav] + [x for x in e["cena"]["npcs"] if x != fav]
            r["saida_ate"] = time.time() + 9 + len(e["cena"].get("texto") or "")*.075
        casa_contagem(e, e.get("play_ate", 0), "⏳ Confessionário e resultado no ar... ({s} s)", revelar)
        return
    st.markdown("### 👋 A despedida")
    if "eu" in r["sai"]:
        st.error(f"😢 **{e['jogador']} foi eliminad{'a' if e['sexo'] == 'F' else 'o'}.** Mas a grande final vem já já.")
    else:
        st.success(f"🏆 **{e['jogador']} está na final** com {' e '.join(nm(x) for x in r['fin'] if x != 'eu')}!")

    def para_final():
        tot = len(casa_vivos(e))
        for i, x in enumerate(r["sai"]):
            if x == "eu":
                e["vivo"] = False
                e["colocacao"] = tot - i
                casa_reg(e, f"😢 {e['jogador']} foi eliminad{'a' if e['sexo'] == 'F' else 'o'} no confessionário ({tot - i}º lugar).")
                casa_hall(e, f"{tot - i}º lugar")
                continue
            e["parts"][x]["vivo"] = False
            e["eliminados"].append(x)
            casa_reg(e, f"👋 {nm(x)} deixou a casa no confessionário.")
        e["fase"] = "final"
        fin = casa_vivos(e)
        if "eu" not in fin:   # você saiu: a final já começa, com os três
            casa_final_iniciar(e, fin)
        else:
            casa_cena(e, "paredao", [x for x in fin if x != "eu"], f"Chegamos à grande final! {', '.join(nm(x) for x in fin[:-1])} e {nm(fin[-1])}: só um de vocês leva o prêmio de um milhão de reais.",
                      enc="paredao", eu=True, quem=None, titulo="🏆 A GRANDE FINAL", capitulo="A última noite")
    casa_contagem(e, r.get("saida_ate", time.time()), "Em {s} s: a grande final 🏆", para_final)


def casa_final_conversas(e, x):
    r = e.get("rodada") or {}
    if x == "eu":
        n = r.get("notas") or {}
        return round(sum(n.values())/len(n), 1) if n else 5.0
    return round(min(8.8, r.get("qual", {}).get(x, 5.0)), 1)


def casa_final_discurso_nota(e, x):
    d = (e.get("defesa") or {}).get(x)
    if d and "nota" in d:
        return d["nota"]
    rng = random.Random(f"{x}{e['jogador']}")
    return round(max(3, min(9, casa_final_conversas(e, x) + rng.gauss(0, .8))), 1)


def casa_final_avaliacao(e, x):
    """Nota final de cada finalista, a que o público usa para votar: 75% as conversas (você pelas suas respostas, os outros pelo assunto que trouxeram) e 25% o discurso."""
    return round(.75*casa_final_conversas(e, x) + .25*casa_final_discurso_nota(e, x), 1)


