                   dict(titulo="A Dalva", tema="amor, casamento, esposa, dança", gatilhos=["amor", "casad", "espos", "mulher", "namor", "dança", "baile", "coração"],
                        lembranca="Dalva... minha Dalva. A gente se conheceu num baile de carnaval em 1962. Ela pisou no meu pé e pediu desculpa dançando."),
