  ctx.fillStyle = '#37474f'; ctx.fillRect(0, 0, W, H); ctx.fillStyle = '#546e7a'; ctx.beginPath(); ctx.roundRect(OX - 14, OY - 14, N*C + 28, N*C + 28, 16); ctx.fill();
  ctx.fillStyle = '#455a64'; ctx.fillRect(OX, OY, N*C, N*C); ctx.strokeStyle = 'rgba(255,255,255,.35)'; ctx.setLineDash([12, 10]); ctx.lineWidth = 2;
